import sys,time
INF=100000000
MATE=100000
VAL={'p':100,'n':320,'b':330,'r':500,'q':900,'k':20000}
PROM={1:'n',2:'b',3:'r',4:'q'}

def attacked(p,sq,by):
    if sq<0 or sq>=64:return False
    b=p.b;r,f=divmod(sq,8)
    rr=r-1 if by==0 else r+1
    pawn='P' if by==0 else 'p'
    if 0<=rr<8:
        for ff in (f-1,f+1):
            if 0<=ff<8 and b[rr*8+ff]==pawn:return True
    knight='N' if by==0 else 'n'
    for dr,df in ((2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)):
        x,y=r+dr,f+df
        if 0<=x<8 and 0<=y<8 and b[x*8+y]==knight:return True
    king='K' if by==0 else 'k'
    for dr in (-1,0,1):
        for df in (-1,0,1):
            if dr or df:
                x,y=r+dr,f+df
                if 0<=x<8 and 0<=y<8 and b[x*8+y]==king:return True
    for dr,df,chars in ((1,0,'rq'),(-1,0,'rq'),(0,1,'rq'),(0,-1,'rq'),(1,1,'bq'),(1,-1,'bq'),(-1,1,'bq'),(-1,-1,'bq')):
        x,y=r+dr,f+df
        while 0<=x<8 and 0<=y<8:
            z=b[x*8+y]
            if z!='.':
                if z.isupper()==(by==0) and z.lower() in chars:return True
                break
            x+=dr;y+=df
    return False

def king_sq(p,side):
    k='K' if side==0 else 'k'
    for i,x in enumerate(p.b):
        if x==k:return i
    return -1

class Position:
    def __init__(self,b,side,cast,ep,half,full):
        self.b=b;self.side=side;self.cast=cast;self.ep=ep;self.half=half;self.full=full
    @classmethod
    def fen(cls,s):
        a=s.split();b=['.']*64
        for ri,row in enumerate(a[0].split('/')):
            sq=(7-ri)*8
            for x in row:
                if x.isdigit():sq+=int(x)
                else:b[sq]=x;sq+=1
        c=0
        for i,x in enumerate('KQkq'):
            if x in a[2]:c|=1<<i
        ep=-1
        if a[3]!='-':ep=ord(a[3][0])-97+8*(int(a[3][1])-1)
        return cls(b,0 if a[1]=='w' else 1,c,ep,int(a[4]),int(a[5]))
    @classmethod
    def start(cls):
        return cls.fen('rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1')

def enc(a,z,pr=0,fl=0):return a|(z<<6)|(pr<<12)|(fl<<16)

def pseudo(p,captures=False):
    b=p.b;white=p.side==0;out=[]
    def add(a,z,pr=0,fl=0,cap=False):
        if not captures or cap or pr:out.append(enc(a,z,pr,fl))
    for s,pc in enumerate(b):
        if pc=='.' or pc.isupper()!=white:continue
        r,f=divmod(s,8);t=pc.lower()
        if t=='p':
            d=8 if white else -8;z=s+d
            prom=0<=z<64 and z//8==(7 if white else 0)
            if 0<=z<64 and b[z]=='.':
                if prom:
                    for q in (4,3,2,1):add(s,z,q)
                else:add(s,z)
                if not captures and r==(1 if white else 6) and b[s+2*d]=='.':add(s,s+2*d,0,4)
            for df in (-1,1):
                if 0<=f+df<8:
                    z=s+d+df
                    if 0<=z<64:
                        x=b[z]
                        if x!='.' and x.isupper()!=white:
                            if z//8==(7 if white else 0):
                                for q in (4,3,2,1):add(s,z,q,0,True)
                            else:add(s,z,0,0,True)
                        elif z==p.ep:add(s,z,0,2,True)
        elif t=='n':
            for dr,df in ((2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)):
                x,y=r+dr,f+df
                if 0<=x<8 and 0<=y<8:
                    z=x*8+y
                    if b[z]=='.' or b[z].isupper()!=white:add(s,z,0,0,b[z]!='.')
        elif t in 'brq':
            ds=[]
            if t in 'bq':ds+=((1,1),(1,-1),(-1,1),(-1,-1))
            if t in 'rq':ds+=((1,0),(-1,0),(0,1),(0,-1))
            for dr,df in ds:
                x,y=r+dr,f+df
                while 0<=x<8 and 0<=y<8:
                    z=x*8+y
                    if b[z]=='.':add(s,z)
                    else:
                        if b[z].isupper()!=white:add(s,z,0,0,True)
                        break
                    x+=dr;y+=df
        else:
            for dr in (-1,0,1):
                for df in (-1,0,1):
                    if dr or df:
                        x,y=r+dr,f+df
                        if 0<=x<8 and 0<=y<8:
                            z=x*8+y
                            if b[z]=='.' or b[z].isupper()!=white:add(s,z,0,0,b[z]!='.')
            if not captures and s==(4 if white else 60) and not attacked(p,s,p.side^1):
                if white and p.cast&1 and b[5]==b[6]=='.' and b[7]=='R' and not attacked(p,5,1) and not attacked(p,6,1):add(s,6,0,1)
                if white and p.cast&2 and b[1]==b[2]==b[3]=='.' and b[0]=='R' and not attacked(p,3,1) and not attacked(p,2,1):add(s,2,0,1)
                if not white and p.cast&4 and b[61]==b[62]=='.' and b[63]=='r' and not attacked(p,61,0) and not attacked(p,62,0):add(s,62,0,1)
                if not white and p.cast&8 and b[57]==b[58]==b[59]=='.' and b[56]=='r' and not attacked(p,59,0) and not attacked(p,58,0):add(s,58,0,1)
    return out

def make(p,m):
    a=m&63;z=(m>>6)&63;pr=(m>>12)&15;fl=m>>16;b=p.b[:];pc=b[a];cap=b[z]
    b[a]='.'
    if fl&2:
        b[z+(-8 if pc.isupper() else 8)]='.';cap='p'
    b[z]=pc
    if fl&1:
        if z==6:b[5]=b[7];b[7]='.'
        elif z==2:b[3]=b[0];b[0]='.'
        elif z==62:b[61]=b[63];b[63]='.'
        elif z==58:b[59]=b[56];b[56]='.'
    if pr:b[z]=('NBRQ'[pr-1] if pc.isupper() else 'nbrq'[pr-1])
    c=p.cast
    if pc=='K':c&=12
    elif pc=='k':c&=3
    if a==0 or z==0:c&=~2
    if a==7 or z==7:c&=~1
    if a==56 or z==56:c&=~8
    if a==63 or z==63:c&=~4
    ep=(a+z)//2 if pc.lower()=='p' and abs(z-a)==16 else -1
    return Position(b,p.side^1,c,ep,0 if pc.lower()=='p' or cap!='.' else p.half+1,p.full+(1 if p.side else 0))

def legal(p,captures=False):
    out=[];side=p.side
    for m in pseudo(p,captures):
        q=make(p,m)
        if not attacked(q,king_sq(q,side),side^1):out.append(m)
    return out

def notation(m):
    a=m&63;z=(m>>6)&63;pr=(m>>12)&15
    s='abcdefgh'[a&7]+str(a//8+1)+'abcdefgh'[z&7]+str(z//8+1)
    return s+(PROM[pr] if pr else '')

class Engine:
    def __init__(self):
        self.pos=Position.start();self.tt={};self.history={};self.killers={};self.nodes=0;self.deadline=0
    def evaluate(self,p):
        score=0;phase=0;wp=[0]*8;bp=[0]*8;bishops=[0,0];pawns=0
        for pc in p.b:
            if pc!='.' and pc.lower() in 'nbrq':phase+=VAL[pc.lower()]
        for s,pc in enumerate(p.b):
            if pc=='.':continue
            typ=pc.lower();sg=1 if pc.isupper() else -1;v=VAL[typ];score+=sg*v
            r,f=divmod(s,8);rr=r if sg==1 else 7-r
            center=7-abs(2*f-7)-abs(2*rr-7)
            if typ=='p':
                pawns+=1;(wp if sg==1 else bp)[f]+=1
                score+=sg*(rr*9+center*3)
                passed=True
                for r2 in range(r+1,8) if sg==1 else range(r-1,-1,-1):
                    for f2 in (f-1,f,f+1):
                        if 0<=f2<8 and p.b[r2*8+f2]==('p' if sg==1 else 'P'):passed=False
                if passed:score+=sg*(20+rr*10)
            elif typ=='n':score+=sg*(center*12)
            elif typ=='b':score+=sg*(center*6);bishops[0 if sg==1 else 1]+=1
            elif typ=='r':
                score+=sg*(rr*4+(8 if f in (3,4) else 0))
                files=wp if sg==1 else bp
                if files[f]==0:score+=sg*15
                if rr==6:score+=sg*18
            elif typ=='q':score+=sg*(center*3)
            else:
                if phase>2600:score-=sg*center*4
                else:score+=sg*center*12
                shield=1 if r==(1 if sg==1 else 6) else 0
                if shield:
                    files=wp if sg==1 else bp
                    score+=sg*sum(7 for ff in (f-1,f,f+1) if 0<=ff<8 and files[ff])
        if bishops[0]>=2:score+=35
        if bishops[1]>=2:score-=35
        for n in wp:score-=max(0,n-1)*14
        for n in bp:score+=max(0,n-1)*14
        for f,n in enumerate(wp):
            if n and (f==0 or wp[f-1]==0) and (f==7 or wp[f+1]==0):score-=12*n
        for f,n in enumerate(bp):
            if n and (f==0 or bp[f-1]==0) and (f==7 or bp[f+1]==0):score+=12*n
        if pawns==0 and phase in (0,320,330):return 0
        return score if p.side==0 else -score
    def tick(self):
        self.nodes+=1
        if (self.nodes&31)==0 and time.perf_counter()>=self.deadline:raise TimeoutError
    def key(self,p):return (''.join(p.b),p.side,p.cast,p.ep)
    def order_score(self,p,m,tt,ply):
        a=m&63;z=(m>>6)&63;pr=(m>>12)&15;fl=m>>16
        sc=100000000 if m==tt else 0
        cap=p.b[z]
        if fl&2:cap='p'
        if cap!='.':sc+=1000000+VAL[cap.lower()]*12-VAL[p.b[a].lower()]
        if pr:sc+=900000+pr*12000
        if fl&1:sc+=300
        if self.killers.get(ply)==m:sc+=500000
        sc+=self.history.get((p.side,a,z),0)
        return sc
    def qsearch(self,p,alpha,beta,ply):
        self.tick();checked=attacked(p,king_sq(p,p.side),p.side^1)
        if checked:
            ms=legal(p,False)
            if not ms:return -MATE+ply
            if ply>=14:return -MATE+ply
        else:
            stand=self.evaluate(p)
            if stand>=beta:return stand
            if stand>alpha:alpha=stand
            if ply>=12:return alpha
            ms=legal(p,True)
            if not ms:return stand
        ms.sort(key=lambda m:self.order_score(p,m,-1,ply),reverse=True)
        for m in ms:
            sc=-self.qsearch(make(p,m),-beta,-alpha,ply+1)
            if sc>=beta:return sc
            if sc>alpha:alpha=sc
        return alpha
    def search(self,p,depth,alpha,beta,ply):
        self.tick()
        if depth<=0:return self.qsearch(p,alpha,beta,ply)
        key=self.key(p);orig=alpha;ent=self.tt.get(key);tt=-1
        if ent:
            ed,ev,flag,tt=ent
            if ed>=depth:
                if flag==0:return ev
                if flag==1:alpha=max(alpha,ev)
                else:beta=min(beta,ev)
                if alpha>=beta:return ev
        ms=legal(p)
        if not ms:
            return -MATE+ply if attacked(p,king_sq(p,p.side),p.side^1) else 0
        ms.sort(key=lambda m:self.order_score(p,m,tt,ply),reverse=True)
        best=-INF;bestm=ms[0];first=True
        for m in ms:
            q=make(p,m);nd=depth-1
            if attacked(q,king_sq(q,q.side),q.side^1):nd+=1
            if first:
                sc=-self.search(q,nd,-beta,-alpha,ply+1);first=False
            else:
                sc=-self.search(q,nd,-alpha-1,-alpha,ply+1)
                if alpha<sc<beta:sc=-self.search(q,nd,-beta,-alpha,ply+1)
            if sc>best:best=sc;bestm=m
            if sc>alpha:alpha=sc
            if alpha>=beta:
                if p.b[m&63].lower()!='p' and p.b[(m>>6)&63]=='.' and not (m>>12)&15:
                    self.killers[ply]=m
                    h=(p.side,m&63,(m>>6)&63)
                    self.history[h]=min(20000,self.history.get(h,0)+depth*depth)
                break
        flag=0 if best>orig and best<beta else 1 if best>=beta else 2
        self.tt[key]=(depth,best,flag,bestm)
        if len(self.tt)>220000:self.tt.clear()
        return best
    def root(self,p,ms,depth):
        ms=ms[:];ms.sort(key=lambda m:self.order_score(p,m,-1,0),reverse=True)
        alpha=-INF;best=-INF;bm=ms[0];first=True
        for m in ms:
            self.tick();q=make(p,m);nd=depth-1
            if attacked(q,king_sq(q,q.side),q.side^1):nd+=1
            if first:
                sc=-self.search(q,nd,-INF,-alpha,1);first=False
            else:
                sc=-self.search(q,nd,-alpha-1,-alpha,1)
                if sc>alpha:sc=-self.search(q,nd,-INF,-alpha,1)
            if sc>best:best=sc;bm=m
            if sc>alpha:alpha=sc
        return best,bm
    def think(self,millis):
        moves=legal(self.pos)
        if not moves:return '0000'
        best=moves[0]
        if millis<=5:return notation(best)
        self.nodes=0;self.deadline=time.perf_counter()+max(0.001,millis/1000.0*0.82)
        for depth in range(1,64):
            try:score,m=self.root(self.pos,moves,depth)
            except TimeoutError:break
            best=m
            if abs(score)>=MATE-1000:break
        return notation(best)
    def setpos(self,a):
        if len(a)>1 and a[1]=='startpos':p=Position.start();i=2
        elif len(a)>=8 and a[1]=='fen':p=Position.fen(' '.join(a[2:8]));i=8
        else:return
        if i<len(a) and a[i]=='moves':
            for u in a[i+1:]:
                for m in legal(p):
                    if notation(m)==u:p=make(p,m);break
        self.pos=p

def main():
    e=Engine()
    for line in sys.stdin:
        a=line.strip().split()
        if not a:continue
        if a[0]=='uci':
            print('id name PythonScratch');print('id author Codex');print('uciok');sys.stdout.flush()
        elif a[0]=='isready':print('readyok');sys.stdout.flush()
        elif a[0]=='ucinewgame':e.tt.clear();e.history.clear();e.killers.clear()
        elif a[0]=='position':e.setpos(a)
        elif a[0]=='go':
            ms=1000
            if 'movetime' in a:
                try:ms=max(1,int(a[a.index('movetime')+1]))
                except Exception:pass
            try:mv=e.think(ms)
            except Exception:
                lm=legal(e.pos);mv=notation(lm[0]) if lm else '0000'
            print('bestmove '+mv);sys.stdout.flush()
        elif a[0]=='quit':break
